import { createModule, t } from "@directive-run/core";

type Phase = "red" | "yellow" | "green";
const NEXT: Record<Phase, Phase> = { red: "green", green: "yellow", yellow: "red" };

export const trafficLight = createModule("traffic-light", {
  schema: {
    facts: { phase: t.string<Phase>() },
    events: { timer: {} },
  },
  init: (facts) => {
    facts.phase = "red";
  },
  events: {
    timer: (facts) => {
      facts.phase = NEXT[facts.phase];
    },
  },
});

