import { createModule, createSystem, t } from "@directive-run/core";
import { createDirectiveContext } from "@directive-run/react";

const counter = createModule("counter", {
  schema: {
    facts: { count: t.number() },
    derivations: { doubled: t.number() },
    events: { increment: {} },
  },
  init: (facts) => { facts.count = 0; },
  derive: { doubled: (facts) => facts.count * 2 },
  events: { increment: (facts) => { facts.count += 1; } },
});

const system = createSystem({ module: counter });
const { useFact, useDerived, useEvents } = createDirectiveContext(system);

function Counter() {
  const count = useFact("count");
  const doubled = useDerived("doubled");
  const { increment } = useEvents();
  return <button onClick={() => increment({})}>{count} ({doubled})</button>;
}

